import time, random

class MockAPI:
    def __init__(self):
        self.attempts = 0
    def fetch(self):
        self.attempts += 1
        if self.attempts < 3:
            return {'status': 429, 'msg': 'Rate limit exceeded'}
        return {'status': 200, 'data': [{'id': 1, 'name': 'Item A'}, {'id': 2, 'name': 'Item B'}]}

api = MockAPI()
delay = 0.5
for attempt in range(1, 5):
    res = api.fetch()
    if res['status'] == 200:
        print(f'Exito en intento {attempt}: {len(res["data"])} registros')
        break
    elif res['status'] == 429:
        jitter = random.uniform(0.05, 0.2)
        time.sleep(delay + jitter)
        delay *= 2
